// PredictScore returns the raw logit for feature vector f.
func PredictScore(f []float64) float64 {
	s := 0.0
	s += tree0(f)
	s += tree1(f)
	s += tree2(f)
	s += tree3(f)
	s += tree4(f)
	s += tree5(f)
	s += tree6(f)
	s += tree7(f)
	s += tree8(f)
	s += tree9(f)
	s += tree10(f)
	s += tree11(f)
	s += tree12(f)
	s += tree13(f)
	s += tree14(f)
	s += tree15(f)
	s += tree16(f)
	s += tree17(f)
	s += tree18(f)
	s += tree19(f)
	s += tree20(f)
	s += tree21(f)
	s += tree22(f)
	s += tree23(f)
	s += tree24(f)
	s += tree25(f)
	s += tree26(f)
	s += tree27(f)
	s += tree28(f)
	s += tree29(f)
	s += tree30(f)
	s += tree31(f)
	s += tree32(f)
	s += tree33(f)
	s += tree34(f)
	s += tree35(f)
	s += tree36(f)
	s += tree37(f)
	s += tree38(f)
	s += tree39(f)
	return bias + scale*s
}

// PredictProbability returns sigmoid(PredictScore(f)).
func PredictProbability(f []float64) float64 {
	x := PredictScore(f)
	if x >= 0 {
		return 1.0 / (1.0 + math.Exp(-x))
	}
	return math.Exp(x) / (1.0 + math.Exp(x))
}

// Predict returns 0 or 1 (threshold 0.5).
func Predict(f []float64) int {
	if PredictScore(f) >= 0 {
		return 1
	}
	return 0
}

